#!/usr/bin/env python3
"""R998：只準備私人觀測來源；不執行原版或GUI。"""
from pathlib import Path
import hashlib
import json
import shutil
import subprocess

HELPER = 'package main\n\n// R998私人唯讀觀測；不參與正式錄製資格或原版推進。\nimport (\n\t"crypto/sha256"\n\t"encoding/hex"\n\t"encoding/json"\n\t"fmt"\n\t"image"\n\t"image/png"\n\t"io"\n\t"os"\n\t"path/filepath"\n\t"sync"\n\n\t"github.com/hajimehoshi/ebiten/v2"\n\t"github.com/wicanr2/dosgolem/oracle"\n\trc "github.com/wicanr2/wizardry7-cht/recording"\n)\n\nvar r998BinaryOnce sync.Once\nvar r998BinarySHA string\n\nfunc r998BinaryIdentity() string {\n\tr998BinaryOnce.Do(func() {\n\t\tf, err := os.Open("/proc/self/exe")\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\th := sha256.New()\n\t\t_, err = io.Copy(h, f)\n\t\tcloseErr := f.Close()\n\t\tif err == nil && closeErr == nil {\n\t\t\tr998BinarySHA = hex.EncodeToString(h.Sum(nil))\n\t\t}\n\t})\n\treturn r998BinarySHA\n}\n\ntype r998Sink struct {\n\tframesInitialized   bool\n\tframeDir            string\n\tmu                  sync.Mutex\n\tenv, kind           string\n\tinitialized, failed bool\n\tfile                *os.File\n\tconfig, binary      string\n\tlastID, lastStep    uint64\n}\n\nvar r998DrawSink = r998Sink{env: "WIZ7_R998_DRAW_RECEIPT", kind: "draw"}\nvar r998StateSink = r998Sink{env: "WIZ7_R998_STATE_RECEIPT", kind: "state"}\n\n// INVALID必須否定整份觀測；不呼叫live.fail或更改錄製/原版狀態。\nfunc (s *r998Sink) invalid(code string) {\n\tif !s.failed {\n\t\ts.failed = true\n\t\tfmt.Fprintf(os.Stderr, "R998_OBSERVER_INVALID kind=%s code=%s\\n", s.kind, code)\n\t\tif s.file != nil {\n\t\t\t_ = s.file.Close()\n\t\t\ts.file = nil\n\t\t}\n\t}\n}\n\nfunc (s *r998Sink) ready(p recordingPublication) bool {\n\tif !s.initialized {\n\t\ts.initialized = true\n\t\tpath := os.Getenv(s.env)\n\t\tif path == "" {\n\t\t\treturn false\n\t\t}\n\t\ts.binary = r998BinaryIdentity()\n\t\tif s.binary == "" {\n\t\t\ts.invalid("binary_identity")\n\t\t\treturn false\n\t\t}\n\t\tf, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)\n\t\tif err != nil {\n\t\t\ts.invalid("open")\n\t\t\treturn false\n\t\t}\n\t\ts.file = f\n\t}\n\tif s.failed || s.file == nil || p.ID == 0 {\n\t\treturn false\n\t}\n\tconfig, err := hex.DecodeString(p.Config)\n\tif err != nil || len(config) != 32 || len(p.Config) != 64 {\n\t\ts.invalid("config_identity")\n\t\treturn false\n\t}\n\tif s.config != "" && s.config != p.Config {\n\t\ts.invalid("config_changed")\n\t\treturn false\n\t}\n\tif p.ID == s.lastID {\n\t\tif p.Step != s.lastStep {\n\t\t\ts.invalid("duplicate_changed")\n\t\t}\n\t\treturn false\n\t}\n\tif p.ID != s.lastID+1 || p.Step < s.lastStep {\n\t\ts.invalid("publication_order")\n\t\treturn false\n\t}\n\ts.config = p.Config\n\treturn true\n}\n\nfunc (s *r998Sink) write(p recordingPublication, value any) {\n\tdata, err := json.Marshal(value)\n\tif err != nil {\n\t\ts.invalid("encode")\n\t\treturn\n\t}\n\tdata = append(data, \'\\n\')\n\tn, err := s.file.Write(data)\n\tif err != nil || n != len(data) {\n\t\ts.invalid("write")\n\t\treturn\n\t}\n\tif s.file.Sync() != nil {\n\t\ts.invalid("sync")\n\t\treturn\n\t}\n\ts.lastID, s.lastStep = p.ID, p.Step\n}\n\nfunc r998ObserveDraw(area *ebiten.Image, scale int, p recordingPublication, panel rc.Panel) {\n\ts := &r998DrawSink\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tdefer func() {\n\t\tif recover() != nil {\n\t\t\ts.invalid("draw_panic")\n\t\t}\n\t}()\n\tif !s.ready(p) {\n\t\treturn\n\t}\n\tw, h := 320*scale, 200*scale\n\tif area == nil || scale < 1 || area.Bounds() != image.Rect(0, 0, w, h) {\n\t\ts.invalid("game_area")\n\t\treturn\n\t}\n\trgba := make([]byte, w*h*4)\n\tarea.ReadPixels(rgba)\n\tpixelSHA := sha256.Sum256(rgba)\n\tif !s.writeFrame(p, w, h, rgba) {\n\t\treturn\n\t}\n\trow := struct {\n\t\tPublication uint64   `json:"publication"`\n\t\tStep        uint64   `json:"step"`\n\t\tConfigSHA   string   `json:"config_sha256"`\n\t\tPanel       rc.Panel `json:"panel"`\n\t\tWidth       int      `json:"width"`\n\t\tHeight      int      `json:"height"`\n\t\tPixelSHA    string   `json:"pixel_sha256"`\n\t\tBinarySHA   string   `json:"binary_sha256"`\n\t}{p.ID, p.Step, p.Config, panel, w, h, hex.EncodeToString(pixelSHA[:]), s.binary}\n\ts.write(p, row)\n}\n\nfunc r998ObserveState(o *oracle.Oracle, p recordingPublication, panel rc.Panel) {\n\ts := &r998StateSink\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tdefer func() {\n\t\tif recover() != nil {\n\t\t\ts.invalid("state_panic")\n\t\t}\n\t}()\n\tif !s.ready(p) {\n\t\treturn\n\t}\n\tstate := recordingOriginalHash(o)\n\tif state.Step != p.Step {\n\t\ts.invalid("state_step")\n\t\treturn\n\t}\n\trow := struct {\n\t\tPublication uint64   `json:"publication"`\n\t\tStep        uint64   `json:"step"`\n\t\tPanel       rc.Panel `json:"panel"`\n\t\tConfigSHA   string   `json:"config_sha256"`\n\t\tBinarySHA   string   `json:"binary_sha256"`\n\t\tTicks       uint64   `json:"ticks"`\n\t\tRAM         string   `json:"ram"`\n\t\tIndexed     string   `json:"indexed"`\n\t\tPalette     string   `json:"palette"`\n\t\tRegisters   string   `json:"registers"`\n\t}{p.ID, p.Step, panel, p.Config, s.binary, state.Ticks, state.RAM, state.Indexed, state.Palette, state.Registers}\n\ts.write(p, row)\n}\n\n// 可選原生像素產物：只編碼當次ReadPixels已取得的同一buffer。\nfunc (s *r998Sink) writeFrame(p recordingPublication, w, h int, rgba []byte) bool {\n\tif !s.framesInitialized {\n\t\ts.framesInitialized = true\n\t\tpath := os.Getenv("WIZ7_R998_FRAME_DIR")\n\t\tif path != "" {\n\t\t\tinfo, err := os.Lstat(path)\n\t\t\tif err != nil || !info.IsDir() {\n\t\t\t\ts.invalid("frame_dir")\n\t\t\t\treturn false\n\t\t\t}\n\t\t\tentries, err := os.ReadDir(path)\n\t\t\tif err != nil || len(entries) != 0 {\n\t\t\t\ts.invalid("frame_dir_not_empty")\n\t\t\t\treturn false\n\t\t\t}\n\t\t\ts.frameDir = path\n\t\t}\n\t}\n\tif s.frameDir == "" {\n\t\treturn true\n\t}\n\tf, err := os.OpenFile(filepath.Join(s.frameDir, fmt.Sprintf("%08d.png", p.ID)), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)\n\tif err != nil {\n\t\ts.invalid("frame_open")\n\t\treturn false\n\t}\n\t// NRGBA保留原buffer四通道bytes，PNG不再抽樣畫面或修改buffer。\n\timg := &image.NRGBA{Pix: rgba, Stride: w * 4, Rect: image.Rect(0, 0, w, h)}\n\tencodeErr := png.Encode(f, img)\n\tcloseErr := f.Close()\n\tif encodeErr != nil {\n\t\ts.invalid("frame_encode")\n\t\treturn false\n\t}\n\tif closeErr != nil {\n\t\ts.invalid("frame_close")\n\t\treturn false\n\t}\n\treturn true\n}\n'

repo, work = Path('/src'), Path('/out')
assert work.stat().st_uid == 1000
source, build = work/'source', work/'build'
assert not source.exists() and not build.exists()
source.mkdir(); build.mkdir()
for name in ['cmd/wiz7', 'initconfig', 'recording']:
    shutil.copytree(repo/name, source/name, symlinks=True)
for name in ['go.mod', 'go.sum', 'tools/re/build_recording.py']:
    target = source/name; target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(repo/name, target)
assert (repo/'worktrees/dosgolem').is_dir()
(source/'worktrees').mkdir()
(source/'worktrees/dosgolem').symlink_to(repo/'worktrees/dosgolem', target_is_directory=True)
assert (source/'go.mod').read_bytes() == (repo/'go.mod').read_bytes()
formal = {str(p.relative_to(source)): hashlib.sha256(p.read_bytes()).hexdigest()
          for p in source.rglob('*') if p.is_file() and not p.is_symlink() and 'worktrees' not in p.relative_to(source).parts}
p = source/'cmd/wiz7/main.go'; s = p.read_text()
old = '\t\t\tg.live.acknowledge(publication, rc.Panel{HelpOpen: hOpen, HelpScreen: hScreen, HelpPage: int64(hPage), MapOpen: mOpen})\n'
assert s.count(old) == 1
s = s.replace(old, '\t\t\tr998ObserveDraw(gameArea, g.scale, publication, rc.Panel{HelpOpen: hOpen, HelpScreen: hScreen, HelpPage: int64(hPage), MapOpen: mOpen})\n'+old)
old = '\t\tsh.mu.Unlock()\n\t\tif published {\n\t\t\tlive.afterPublish(publication)\n'
assert s.count(old) == 1
s = s.replace(old, '\t\tif published {\n\t\t\tr998ObserveState(o, publication, rc.Panel{HelpOpen: sh.helpOpen, HelpScreen: sh.helpScreen, HelpPage: int64(sh.helpPage), MapOpen: sh.mapOpen})\n\t\t}\n'+old)
p.write_text(s)
(source/'cmd/wiz7/r998_observer.go').write_text(HELPER)
subprocess.run(['gofmt','-w',str(p),str(source/'cmd/wiz7/r998_observer.go')],check=True)
(build/'formal-copy-inputs.json').write_text(json.dumps(formal,indent=2)+'\n')
print(json.dumps({'prepared':True,'formal_regular_files':len(formal),'main_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'observer_sha256':hashlib.sha256((source/'cmd/wiz7/r998_observer.go').read_bytes()).hexdigest()}))
